    (p -> arrayMap(dep -> arrayMap(wc -> arrayMap(wav -> arrayMap(fine -> arrayMap(refx -> arrayMap(path -> arrayMap(gold -> arrayMap(blue -> arrayMap(wr -> wr, [tuplePlus(wc,tuplePlus(tupleMultiplyByNumber((1.,.59,.25),gold),tupleMultiplyByNumber((.58,.76,.75),blue)))])[1], [wav*(.028+.060*dep)+fine])[1], [path*(.075+wav*.43)*(1.-dep*.25)])[1], [exp(-pow((p.1-refx)/(19.+dep*120.),2))])[1], [1217.+sin(p.2*.087)*13.+sin(p.2*.231)*7.])[1], [sin(p.2*1.30+sin(p.1*.037)*2.3)*.012*dep])[1], [pow(.5+.5*sin(p.2*.54+sin(p.1*.018)*1.7+sin(p.1*.047+p.2*.033)),18.)])[1], [mix((0.49,0.56,0.59),(0.105,0.29,0.34),pow(dep,.40))])[1], [clamp((p.2-473.)/527.,0.,1.)])[1]) AS water
